INSERT INTO public.layer_catalog (state,provider,renderer,premium_tier,enabled,release_status,min_zoom,attribution,update_frequency,usage_notes,id,name,category,service_url,layer_ids,source_url,description,dataset_metadata) VALUES ('NSW','NSW Department of Communities and Justice','geojson','free',false,'beta',7,'© State of New South Wales (DCJ), Report 156; ABS LGA 2025 boundaries. CC BY 4.0. LandOS unit conversion and code crosswalk; simplified display geometry.','Quarterly; controlled import','LGA sale medians, not property valuations or suburb estimates. Non Strata / Strata are not universal house / unit definitions.','nsw-median-sales','NSW median sale prices · LGA','Property Market','https://geo.abs.gov.au/arcgis/rest/services/ASGS2025/LGA/MapServer','1','https://dcj.nsw.gov.au/about-us/families-and-communities-statistics/housing-rent-and-sales/rent-and-sales-report.html','Published aggregate sale medians, volumes and median changes. March quarter 2026, by original Total / Non Strata / Strata classifications; no individual property sales records.','{"licence":"Creative Commons Attribution 4.0 International","licence_url":"https://creativecommons.org/licenses/by/4.0/","licence_evidence":"https://dcj.nsw.gov.au/statements/copyright-and-disclaimer.html","verified_on":"2026-10-31","version":"DCJ Rent and Sales Report 156 · Sales March 2026 quarter","coverage":"126 matched NSW LGAs; original 127 LGA source labels. Armidale Regional unresolved; Balranald has no source sales row. Other non-spatial areas remain unavailable.","geography":"LGA","boundary_version":"ABS ASGS Edition 3 · LGA 2025","reference_period":"March quarter 2026 (contract dates)","updated":"Extracted 31 July 2026 · Report 156","methodology":"DCJ Report 156 aggregate LGA tables, extracted 31 July 2026. One original statewide LGA scope is selected; repeated regional rollups are not summed. Published labels map through the reviewed ABS code crosswalk to current LGA 2025 reference boundaries. Armidale Regional remains unmapped because its historical code is not the current Armidale code. Source boundary vintage is unspecified; no historical boundary reconstruction. s means a sample of 11–30 with count restrictions/caution; - means ten or fewer or unavailable. Original markers and missing values are retained, never zero-filled. Published quarterly/annual changes compare medians, not a quality-adjusted index. Source procedures changed in September 2017. NSW and Victorian dwelling definitions/methods are distinct. Original prices in $000 are converted to AUD. Contract dates, not settlement dates; about 80% of notifications are available after three months. Upper/lower 5% of sales are excluded within each LGA. Only this quarter is imported; published changes do not create an invented historical price series.","fields":["LGA_CODE_2025","LGA_NAME_2025","source_local_government_area","published_category","median_price_aud","sales_count","annual_median_change_percent","quarterly_median_change_percent","median_price_aud_source_marker","sales_count_source_marker","annual_median_change_percent_source_marker","quarterly_median_change_percent_source_marker"],"periods":["2026Q1"],"period_labels":{"2026Q1":"March quarter 2026"},"default_period":"2026Q1","default_indicator":"median_total","indicators":[{"id":"median_total","label":"Median sale price · all sales","unit":"aud","breaks":[400000,600000,800000,1200000,1800000]},{"id":"median_non_strata","label":"Median sale price · Non Strata","unit":"aud","breaks":[400000,600000,800000,1200000,1800000]},{"id":"median_strata","label":"Median sale price · Strata","unit":"aud","breaks":[300000,450000,600000,800000,1100000]},{"id":"sales_total","label":"Sales volume · all sales","unit":"count","breaks":[10,30,100,300,1000]},{"id":"sales_non_strata","label":"Sales volume · Non Strata","unit":"count","breaks":[10,30,100,300,1000]},{"id":"sales_strata","label":"Sales volume · Strata","unit":"count","breaks":[10,30,100,300,1000]},{"id":"annual_change","label":"Annual median sale price change · all sales","unit":"percent","breaks":[-5,0,5,10,20]},{"id":"quarterly_change","label":"Quarterly median sale price change · all sales","unit":"percent","breaks":[-5,0,2,5,10]}]}') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.layer_catalog (state,provider,renderer,premium_tier,enabled,release_status,min_zoom,attribution,update_frequency,usage_notes,id,name,category,service_url,layer_ids,source_url,description,dataset_metadata) VALUES ('NSW','NSW Department of Communities and Justice','geojson','free',false,'beta',7,'© State of New South Wales (DCJ), Report 156; ABS LGA 2025 boundaries. CC BY 4.0. LandOS code crosswalk and simplified display geometry.','Quarterly; controlled import','Bond-based new tenancy rents, not advertised asking rents or the median of all existing tenancies. Total bonds held is a separate stock measure.','nsw-median-rent','NSW median weekly rent · LGA','Property Market','https://geo.abs.gov.au/arcgis/rest/services/ASGS2025/LGA/MapServer','1','https://dcj.nsw.gov.au/about-us/families-and-communities-statistics/housing-rent-and-sales/rent-and-sales-report.html','June quarter 2026 new-bond median weekly rents, published dwelling/bedroom categories, bond counts and median changes. Original aggregate LGA statistics.','{"licence":"Creative Commons Attribution 4.0 International","licence_url":"https://creativecommons.org/licenses/by/4.0/","licence_evidence":"https://dcj.nsw.gov.au/statements/copyright-and-disclaimer.html","verified_on":"2026-10-31","version":"DCJ Rent and Sales Report 156 · Rent June 2026 quarter","coverage":"127 matched NSW LGAs from 128 source labels. Armidale Regional unresolved; suppressed medians remain missing, including Balranald.","geography":"LGA","boundary_version":"ABS ASGS Edition 3 · LGA 2025","reference_period":"June quarter 2026 (new rental bonds)","updated":"Extracted 31 July 2026 · Report 156","methodology":"DCJ Report 156 aggregate LGA tables, extracted 31 July 2026. One original statewide LGA scope is selected; repeated regional rollups are not summed. Published labels map through the reviewed ABS code crosswalk to current LGA 2025 reference boundaries. Armidale Regional remains unmapped because its historical code is not the current Armidale code. Source boundary vintage is unspecified; no historical boundary reconstruction. s means a sample of 11–30 with count restrictions/caution; - means ten or fewer or unavailable. Original markers and missing values are retained, never zero-filled. Published quarterly/annual changes compare medians, not a quality-adjusted index. Source procedures changed in September 2017. NSW and Victorian dwelling definitions/methods are distinct. Median weekly rents use private-market new rental bonds, excluding social housing and retaining original dwelling and bedroom combinations; they are not advertised asking rents, occupied-stock rents, or Victoria''s moving annual suburb medians. Total bonds held is a stock of lodged bonds, not new lettings or all existing tenancies. Only June quarter 2026 is imported; historical rent levels are not inferred from changes.","fields":["LGA_CODE_2025","LGA_NAME_2025","source_local_government_area","published_category","median_weekly_rent_aud","new_bonds_count","total_bonds_held_count","annual_median_change_percent","quarterly_median_change_percent","median_weekly_rent_aud_source_marker","new_bonds_count_source_marker","total_bonds_held_count_source_marker","annual_median_change_percent_source_marker","quarterly_median_change_percent_source_marker"],"periods":["2026Q2"],"period_labels":{"2026Q2":"June quarter 2026"},"default_period":"2026Q2","default_indicator":"median_all","indicators":[{"id":"median_all","label":"Median weekly rent · all dwellings / bedrooms","unit":"aud","breaks":[300,450,600,750,1000]},{"id":"median_house","label":"Median weekly rent · House / all bedrooms","unit":"aud","breaks":[300,450,600,750,1000]},{"id":"median_flat_unit","label":"Median weekly rent · Flat/Unit / all bedrooms","unit":"aud","breaks":[300,450,600,750,1000]},{"id":"median_house_3","label":"Median weekly rent · House / 3 bedrooms","unit":"aud","breaks":[300,450,600,750,1000]},{"id":"median_flat_unit_2","label":"Median weekly rent · Flat/Unit / 2 bedrooms","unit":"aud","breaks":[300,450,600,750,1000]},{"id":"new_bonds","label":"New bonds · all dwellings / bedrooms","unit":"count","breaks":[10,30,100,500,2000]},{"id":"total_bonds_held","label":"Total bonds held · all dwellings / bedrooms","unit":"count","breaks":[100,1000,5000,20000,50000]},{"id":"annual_change","label":"Annual median rent change · all dwellings / bedrooms","unit":"percent","breaks":[-5,0,5,10,20]},{"id":"quarterly_change","label":"Quarterly median rent change · all dwellings / bedrooms","unit":"percent","breaks":[-5,0,2,5,10]}]}') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.layer_catalog (state,provider,renderer,premium_tier,enabled,release_status,min_zoom,attribution,update_frequency,usage_notes,id,name,category,service_url,layer_ids,source_url,description,dataset_metadata) VALUES ('NSW','NSW Bureau of Crime Statistics and Research','geojson','free',false,'beta',7,'© NSW Bureau of Crime Statistics and Research, Creative Commons Attribution; ABS LGA 2025 boundaries CC BY 4.0. LandOS twelve-month sums and reviewed code mapping; simplified display geometry.','Quarterly; controlled import of monthly observations','Recorded incidents are not convictions or individual risk. NSW incident categories and Victorian recorded-offence statistics have different definitions.','nsw-recorded-incidents','NSW recorded criminal incidents · LGA','Crime & Community Safety','https://geo.abs.gov.au/arcgis/rest/services/ASGS2025/LGA/MapServer','1','https://bocsar.nsw.gov.au/statistics-dashboards/open-datasets/criminal-offences-data.html','Selected BOCSAR recorded incident categories, summed from original monthly LGA counts into years ending June 2017–2026. No fabricated crime total or incompatible population rate.','{"licence":"Creative Commons Attribution (BOCSAR); CC BY 4.0 (ABS boundaries)","licence_url":"https://opendefinition.org/licenses/cc-by/","licence_evidence":"https://data.nsw.gov.au/data/dataset/nsw-crime-and-policing-statistics/resource/1d5b2851-52e9-4327-a81b-19149c63f736","verified_on":"2026-10-31","version":"BOCSAR RCI offence-by-month workbook · June 2026 release","coverage":"128 bounded NSW councils. In Custody, Lord Howe Island and Unincorporated Far West are not mapped to neighbouring LGAs.","geography":"LGA","boundary_version":"ABS ASGS Edition 3 · LGA 2025","reference_period":"Years ending 30 June 2017–2026","updated":"2026-09-16","methodology":"Each displayed annual count sums the twelve original numeric monthly observations from July to June for that exact BOCSAR LGA/category. Any missing month remains missing; categories are not combined into a misleading grand total. Original crime categories are preserved, with no new population denominator or cross-state ranking. Current ABS LGA 2025 boundaries and an explicit code crosswalk are display references; source boundary vintage is unspecified and historical boundaries are not reconstructed. Special/non-spatial records remain unmapped. The XLSM is read as data; macros are never executed.","fields":["LGA_CODE_2025","LGA_NAME_2025","source_local_government_area","break_enter_dwelling","break_enter_non_dwelling","motor_vehicle_theft","domestic_violence_assault","non_domestic_violence_assault"],"periods":["2026","2025","2024","2023","2022","2021","2020","2019","2018","2017"],"default_period":"2026","default_indicator":"break_enter_dwelling","indicators":[{"id":"break_enter_dwelling","label":"Break and enter · dwelling incidents","unit":"count","breaks":[10,50,100,250,500]},{"id":"break_enter_non_dwelling","label":"Break and enter · non-dwelling incidents","unit":"count","breaks":[10,50,100,250,500]},{"id":"motor_vehicle_theft","label":"Motor vehicle theft incidents","unit":"count","breaks":[10,50,100,250,500]},{"id":"domestic_violence_assault","label":"Domestic violence related assault incidents","unit":"count","breaks":[50,100,250,500,1000]},{"id":"non_domestic_violence_assault","label":"Non-domestic violence related assault incidents","unit":"count","breaks":[50,100,250,500,1000]}]}') ON CONFLICT (id) DO NOTHING;
